{
  "root_causes": [
    {
      "service": "ts-travel2-service",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "log",
          "sql": "SELECT service_name, level, count(*) n, min(time) t0, max(time) t1 FROM normal_logs WHERE service_name = 'ts-travel2-service' GROUP BY ALL UNION ALL SELECT service_name, level, count(*), min(time), max(time) FROM abnormal_logs WHERE service_name = 'ts-travel2-service' GROUP BY ALL",
          "claim": "ts-travel2-service logs run until 03:47:26 in normal and produce no logs at all in the abnormal window."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'normal' p, count(*) n FROM normal_traces WHERE service_name = 'ts-travel2-service' UNION ALL SELECT 'abnormal', count(*) FROM abnormal_traces WHERE service_name = 'ts-travel2-service'",
          "claim": "ts-travel2-service emits about 1212 spans in normal and zero spans in the abnormal window."
        },
        {
          "kind": "metric",
          "sql": "SELECT time, metric, value FROM abnormal_metrics WHERE attr_k8s_pod_name = 'ts-travel2-service-cb84684f8-cqwpw' AND metric = 'k8s.container.restarts' ORDER BY time LIMIT 5",
          "claim": "The travel2 pod's container restart counter reads 1 from about 03:47:32, shortly after the abnormal window starts, and stays there."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' p, metric, round(avg(value),1) avgv FROM abnormal_metrics WHERE attr_k8s_pod_name = 'ts-travel2-service-cb84684f8-cqwpw' AND metric = 'container.memory.rss' GROUP BY ALL UNION ALL SELECT 'norm', metric, round(avg(value),1) FROM normal_metrics WHERE attr_k8s_pod_name = 'ts-travel2-service-cb84684f8-cqwpw' AND metric = 'container.memory.rss' GROUP BY ALL",
          "claim": "travel2 container RSS falls from about 784 MB in normal to about 317 KB in abnormal, consistent with a fresh container after restart."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel2-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind, span_name, attr_http_response_status_code code, attr_status_code st, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name = 'ts-route-plan-service' AND attr_span_kind = 'Client' GROUP BY ALL",
          "claim": "route-plan's outgoing calls return 503 errors averaging about 3.6 s, and 200 responses averaging about 0.9 s, once travel2 is gone."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_response_status_code code, attr_status_code st, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name IN ('ts-route-plan-service','ts-travel-plan-service') AND attr_span_kind = 'Server' GROUP BY ALL",
          "claim": "route-plan server spans return 500 with about 4.2 s latency, and travel-plan's cheapest route calls return 500 or 504 at about 60 s."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_response_status_code code, attr_status_code st, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name = 'ts-ui-dashboard' AND attr_span_kind = 'Server' AND span_name LIKE '%travelPlan%' GROUP BY ALL",
          "claim": "ui-dashboard's travelPlan requests take about 20 s on average and some return errors, after travel-plan fails."
        }
      ]
    },
    {
      "from": "ts-travel2-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_response_status_code code, attr_status_code st, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name = 'ts-ui-dashboard' AND attr_span_kind = 'Server' AND span_name LIKE '%travel2service%' GROUP BY ALL",
          "claim": "ui-dashboard's /travel2service/trips/left requests return 503 errors averaging about 3.5 s, directly reaching users."
        }
      ]
    }
  ]
}
